        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt") {
            @Override
            public String getName() {
                return null;
            }
        };
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt") {
            @Override
            public String getName() {
                return null;
            }
        };
        // Setting comments to match to focus on name logic
        entry1.setComment("");
        entry2.setComment("");
        // If names are null, it proceeds to comment/extra/gpb check
        // We need to ensure gpb and extra match to return true
        entry2.setGeneralPurposeBit(entry1.getGeneralPurposeBit());
        assertTrue(entry1.equals(entry2));
    }








}

